<?php
namespace App\Http\Controllers;
use App\Models\ShortLink; use App\Services\AuditLogger; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class BulkLinkController extends Controller { public function create():View{return view('links.bulk');} public function store(Request $request):RedirectResponse { $request->validate(['csv'=>['required','file','mimes:csv,txt','max:2048']]); $handle=fopen($request->file('csv')->getRealPath(),'r'); $header=array_map('strtolower',array_map('trim',fgetcsv($handle) ?: [])); if(!in_array('destination_url',$header,true)) return back()->withErrors(['csv'=>'CSV must include destination_url column.']); $created=0;$skipped=0; while(($row=fgetcsv($handle))!==false){$data=array_combine($header,array_pad($row,count($header),null));$url=trim((string)($data['destination_url']??''));if(!filter_var($url,FILTER_VALIDATE_URL)){$skipped++;continue;} $code=strtolower(trim((string)($data['code']??'')));if(!$code){do{$code=(string)random_int(100000,999999);}while(ShortLink::withTrashed()->where('code',$code)->exists());} if(!preg_match('/^[a-z0-9][a-z0-9_-]{1,49}$/',$code)||ShortLink::withTrashed()->where('code',$code)->exists()){$skipped++;continue;} ShortLink::create(['title'=>$data['title']??null,'code'=>$code,'destination_url'=>$url,'code_type'=>isset($data['code'])&&$data['code']?'custom':'random','is_active'=>true,'created_by'=>$request->user()->id,'updated_by'=>$request->user()->id]);$created++;} fclose($handle);AuditLogger::log('bulk_import',new ShortLink(),'Imported '.$created.' short links');return redirect()->route('links.index')->with('success',"Imported {$created} links. Skipped {$skipped} invalid rows.");} }
